import { axialToPixel, createHexGrid, hexDistance, hexLine, } from "./hex.js";
export class TopologyModel {
    radius;
    columns;
    rows;
    originQ;
    originR;
    cells;
    entities;
    relationships;
    constructor(options) {
        this.radius = options.radius;
        this.columns = options.columns;
        this.rows = options.rows;
        this.originQ = options.originQ ?? 0;
        this.originR = options.originR ?? 0;
        this.entities = options.entities ?? [];
        this.relationships = options.relationships ?? [];
        this.cells = createHexGrid({
            radius: this.radius,
            columns: this.columns,
            rows: this.rows,
            originQ: this.originQ,
            originR: this.originR,
        });
    }
    getCell(coord) {
        return this.cells.find((cell) => cell.q === coord.q && cell.r === coord.r);
    }
    getEntity(id) {
        return this.entities.find((entity) => entity.id === id);
    }
    getEntityPosition(id) {
        const entity = this.getEntity(id);
        if (!entity)
            return null;
        return axialToPixel({ q: entity.q, r: entity.r }, this.radius);
    }
    getRelationshipsForEntity(id) {
        return this.relationships.filter((relationship) => relationship.from === id || relationship.to === id);
    }
    getPathBetweenEntities(fromId, toId) {
        const from = this.getEntity(fromId);
        const to = this.getEntity(toId);
        if (!from || !to)
            return [];
        return hexLine({ q: from.q, r: from.r }, { q: to.q, r: to.r });
    }
    getDistanceBetweenEntities(fromId, toId) {
        const from = this.getEntity(fromId);
        const to = this.getEntity(toId);
        if (!from || !to)
            return null;
        return hexDistance({ q: from.q, r: from.r }, { q: to.q, r: to.r });
    }
    getRing(center, distance) {
        if (distance === 0)
            return [center];
        const directions = [
            { q: 1, r: 0 },
            { q: 1, r: -1 },
            { q: 0, r: -1 },
            { q: -1, r: 0 },
            { q: -1, r: 1 },
            { q: 0, r: 1 },
        ];
        let coord = {
            q: center.q + directions[4].q * distance,
            r: center.r + directions[4].r * distance,
        };
        const results = [];
        for (const direction of directions) {
            for (let i = 0; i < distance; i++) {
                results.push(coord);
                coord = {
                    q: coord.q + direction.q,
                    r: coord.r + direction.r,
                };
            }
        }
        return results;
    }
    getSpiral(center, radius) {
        const results = [];
        for (let distance = 0; distance <= radius; distance++) {
            results.push(...this.getRing(center, distance));
        }
        return results;
    }
}
